-- ============================================
-- LUMA — Thème 11 : LONG 2/3 x4 — Bénévolat sur l'événement avec responsabilités
-- ============================================


update scenarios set content = '{"characters": {"coordinator": "le coordinateur", "attendee1": "festivalier 1", "attendee2": "le parent", "security": "la sécurité"}, "start_node": "n1", "nodes": {"n1": {"speaker": "coordinator", "text": "Welcome to the volunteer team! You''ll be at the main entrance, helping with wristbands today.", "text_fr": "Bienvenue dans l''équipe de bénévoles ! Vous serez à l''entrée principale, pour aider avec les bracelets aujourd''hui.", "choices": [{"text": "Sounds great, what exactly should I do if there''s an issue?", "text_fr": "Ça marche, je fais quoi exactement s''il y a un problème ?", "next": "n2"}, {"text": "I''m ready! Any tips for a first-time volunteer?", "text_fr": "Je suis prêt ! Des conseils pour un bénévole débutant ?", "next": "n2b"}]}, "n2": {"speaker": "coordinator", "text": "If tickets don''t scan, radio me immediately. Otherwise, just keep the line moving smoothly.", "text_fr": "Si les billets scannent pas, appelez-moi par radio immédiatement. Sinon, gardez juste la file fluide.", "choices": [{"text": "Got it, I''ll radio you if anything comes up.", "text_fr": "Compris, je vous appelle si quelque chose se présente.", "next": "n3"}]}, "n2b": {"speaker": "coordinator", "text": "Stay patient, smile a lot, and don''t be afraid to ask for help if overwhelmed.", "text_fr": "Restez patient, souriez beaucoup, et n''ayez pas peur de demander de l''aide si vous êtes dépassé.", "choices": [{"text": "That''s really reassuring advice, thank you.", "text_fr": "C''est un conseil vraiment rassurant, merci.", "next": "n3"}]}, "n3": {"speaker": "attendee1", "text": "My ticket won''t scan! I bought this weeks ago, I swear!", "text_fr": "Mon billet scanne pas ! Je l''ai acheté il y a des semaines, je le jure !", "choices": [{"text": "No worries, let''s check your email confirmation together.", "text_fr": "Pas de souci, vérifions ensemble votre email de confirmation.", "next": "n4"}, {"text": "Let me radio my coordinator for help with this.", "text_fr": "Laissez-moi appeler mon coordinateur pour de l''aide.", "next": "n4b"}]}, "n4": {"speaker": "you_thought", "text": "(You find the issue — a typo in the ticket number causing the scan failure.)", "text_fr": "(Vous trouvez le problème — une faute de frappe dans le numéro de billet causant l''échec du scan.)", "choices": [{"text": "Found it! Let me manually verify this and get you through.", "text_fr": "Trouvé ! Laissez-moi vérifier manuellement et vous faire entrer.", "next": "n5"}]}, "n4b": {"speaker": "coordinator", "text": "(Arrives quickly) Let''s see... ah, I can manually verify this one for you.", "text_fr": "(Arrive rapidement) Voyons... ah, je peux vérifier celui-ci manuellement pour vous.", "choices": [{"text": "Thank you for the quick help!", "text_fr": "Merci pour l''aide rapide !", "next": "n5"}]}, "n5": {"speaker": "attendee1", "text": "Thank you so much! I was really worried I''d miss the whole first act.", "text_fr": "Merci beaucoup ! J''avais vraiment peur de rater tout le premier concert.", "choices": [{"text": "You''re all set now, enjoy the festival!", "text_fr": "Vous êtes prêt maintenant, profitez du festival !", "next": "n6"}]}, "n6": {"speaker": "attendee2", "text": "(Approaches, visibly distressed) I think I lost my child in the crowd near here!", "text_fr": "(S''approche, visiblement en détresse) Je pense avoir perdu mon enfant dans la foule près d''ici !", "choices": [{"text": "Stay calm, let''s radio security immediately with a description.", "text_fr": "Restez calme, appelons la sécurité immédiatement avec une description.", "next": "n7"}, {"text": "What does your child look like? I''ll help you look right now.", "text_fr": "À quoi ressemble votre enfant ? Je vais vous aider à chercher tout de suite.", "next": "n7"}]}, "n7": {"speaker": "you_thought", "text": "(You quickly radio the description to festival security while keeping the parent calm.)", "text_fr": "(Vous transmettez rapidement la description à la sécurité du festival tout en gardant le parent calme.)", "choices": [{"text": "They''re on it — let''s stay here in case your child comes looking for you.", "text_fr": "Ils s''en occupent — restons ici au cas où votre enfant viendrait vous chercher.", "next": "n8"}]}, "n8": {"speaker": "security", "text": "(Radio) Found the child near the food trucks, bringing them to the entrance now.", "text_fr": "(Radio) Enfant trouvé près des camions food, on l''amène à l''entrée maintenant.", "choices": [{"text": "(Relay the good news to the relieved parent.)", "text_fr": "(Relaie la bonne nouvelle au parent soulagé.)", "next": "n9"}]}, "n9": {"speaker": "attendee2", "text": "(Reunited with child, tears of relief) Thank you, thank you so much for staying calm and helping.", "text_fr": "(Retrouvailles avec l''enfant, larmes de soulagement) Merci, merci beaucoup d''être resté calme et d''avoir aidé.", "choices": [{"text": "I''m just glad they''re safe. That''s what matters most.", "text_fr": "Je suis juste content qu''il soit en sécurité. C''est ce qui compte le plus.", "next": "n10"}]}, "n10": {"speaker": "coordinator", "text": "(Later) I heard about the lost child situation — you handled that really well today.", "text_fr": "(Plus tard) J''ai entendu parler de la situation de l''enfant perdu — vous avez très bien géré ça aujourd''hui.", "choices": [{"text": "Thank you, it felt good to actually help make a difference.", "text_fr": "Merci, ça faisait du bien de vraiment aider et faire une différence.", "next": "end_volunteer"}]}, "end_volunteer": {"speaker": "coordinator", "text": "That''s exactly why we need volunteers like you. Thank you for everything today.", "text_fr": "C''est exactement pour ça qu''on a besoin de bénévoles comme vous. Merci pour tout aujourd''hui.", "end": true, "ending_label": "Bénévolat marqué par de vraies responsabilités assumées 🎫🙌"}}}'::jsonb, is_playable = true
where title = 'Bénévolat sur l''''événement avec responsabilités'
  and theme_id = (select id from scenario_themes where position = 11 and language_id = (select id from languages where code = 'en'));
